/** kor::I64Vec2: 2 Longs. Its arithmetic wraps, as a Long does. */
data class I64Vec2(var x: Long, var y: Long) {
    constructor(s: Long) : this(s, s)
    /** The first 2 of a I64Vec3 (C++'s explicit conversion). */
    constructor(v: I64Vec3) : this(v.x, v.y)
    /** The first 2 of a I64Vec4 (C++'s explicit conversion). */
    constructor(v: I64Vec4) : this(v.x, v.y)

    operator fun get(i: Int): Long = when (i) { 0 -> x; 1 -> y; else -> throw IndexOutOfBoundsException(i) }
    /** The same with component i replaced: `v.with(1, value)`. */
    fun with(i: Int, value: Long) = when (i) { 0 -> copy(x = value); 1 -> copy(y = value); else -> throw IndexOutOfBoundsException(i) }
    fun toArray() = longArrayOf(x, y)
    operator fun plus(o: I64Vec2) = I64Vec2((x + o.x).toLong(), (y + o.y).toLong())
    operator fun plus(s: Long) = I64Vec2((x + s).toLong(), (y + s).toLong())
    operator fun minus(o: I64Vec2) = I64Vec2((x - o.x).toLong(), (y - o.y).toLong())
    operator fun minus(s: Long) = I64Vec2((x - s).toLong(), (y - s).toLong())
    operator fun times(o: I64Vec2) = I64Vec2((x * o.x).toLong(), (y * o.y).toLong())
    operator fun times(s: Long) = I64Vec2((x * s).toLong(), (y * s).toLong())
    operator fun div(o: I64Vec2) = I64Vec2((x / o.x).toLong(), (y / o.y).toLong())
    operator fun div(s: Long) = I64Vec2((x / s).toLong(), (y / s).toLong())
    operator fun rem(o: I64Vec2) = I64Vec2((x % o.x).toLong(), (y % o.y).toLong())
    operator fun rem(s: Long) = I64Vec2((x % s).toLong(), (y % s).toLong())
    operator fun unaryPlus() = this
    operator fun unaryMinus() = I64Vec2((-x).toLong(), (-y).toLong())
    infix fun and(o: I64Vec2) = I64Vec2((x and o.x).toLong(), (y and o.y).toLong())
    infix fun and(s: Long) = I64Vec2((x and s).toLong(), (y and s).toLong())
    infix fun or(o: I64Vec2) = I64Vec2((x or o.x).toLong(), (y or o.y).toLong())
    infix fun or(s: Long) = I64Vec2((x or s).toLong(), (y or s).toLong())
    infix fun xor(o: I64Vec2) = I64Vec2((x xor o.x).toLong(), (y xor o.y).toLong())
    infix fun xor(s: Long) = I64Vec2((x xor s).toLong(), (y xor s).toLong())
    infix fun shl(s: Int) = I64Vec2((x shl s).toLong(), (y shl s).toLong())
    infix fun shr(s: Int) = I64Vec2((x shr s).toLong(), (y shr s).toLong())
    fun inv() = I64Vec2(x.inv().toLong(), y.inv().toLong())
    fun toVec2() = Vec2(x.toFloat(), y.toFloat())
    fun toDVec2() = DVec2(x.toDouble(), y.toDouble())
    fun toIVec2() = IVec2(x.toInt(), y.toInt())
    fun toUVec2() = UVec2(x.toUInt(), y.toUInt())
    fun toI8Vec2() = I8Vec2(x.toByte(), y.toByte())
    fun toU8Vec2() = U8Vec2(x.toUByte(), y.toUByte())
    fun toI16Vec2() = I16Vec2(x.toShort(), y.toShort())
    fun toU16Vec2() = U16Vec2(x.toUShort(), y.toUShort())
    fun toU64Vec2() = U64Vec2(x.toULong(), y.toULong())
    override fun toString() = "($x, $y)"

    companion object {
        val Zero get() = I64Vec2(0.toLong())
        val One get() = I64Vec2(1.toLong())
        val UnitX get() = I64Vec2(1.toLong(), 0.toLong())
        val UnitY get() = I64Vec2(0.toLong(), 1.toLong())
    }
}
