    fun toU8Vec3() = U8Vec3(x.toUByte(), y.toUByte(), z.toUByte())
    fun toI16Vec3() = I16Vec3(x.toShort(), y.toShort(), z.toShort())
    fun toU16Vec3() = U16Vec3(x.toUShort(), y.toUShort(), z.toUShort())
    fun toI64Vec3() = I64Vec3(x.toLong(), y.toLong(), z.toLong())
    override fun toString() = "($x, $y, $z)"

    companion object {
        val Zero get() = U64Vec3(0.toULong())
        val One get() = U64Vec3(1.toULong())
        val UnitX get() = U64Vec3(1.toULong(), 0.toULong(), 0.toULong())
        val UnitY get() = U64Vec3(0.toULong(), 1.toULong(), 0.toULong())
        val UnitZ get() = U64Vec3(0.toULong(), 0.toULong(), 1.toULong())
    }
}
/** A U64Vec3 from Longs, as their bits. */
fun U64Vec3(x: Long, y: Long, z: Long) = U64Vec3(x.toULong(), y.toULong(), z.toULong())
fun U64Vec3(s: Long) = U64Vec3(s.toULong())
fun IVec3.toU64Vec3() = U64Vec3(x.toULong(), y.toULong(), z.toULong())
fun UVec3.toU64Vec3() = U64Vec3(x.toULong(), y.toULong(), z.toULong())

/** kor::U64Vec4: 4 ULongs. Its arithmetic wraps, as a ULong does. */
data class U64Vec4(var x: ULong, var y: ULong, var z: ULong, var w: ULong) {
    constructor(s: ULong) : this(s, s, s, s)
    constructor(xyz: U64Vec3, w: ULong) : this(xyz.x, xyz.y, xyz.z, w)
    constructor(x: ULong, yzw: U64Vec3) : this(x, yzw.x, yzw.y, yzw.z)
    constructor(xy: U64Vec2, z: ULong, w: ULong) : this(xy.x, xy.y, z, w)
    constructor(x: ULong, y: ULong, zw: U64Vec2) : this(x, y, zw.x, zw.y)
    constructor(xy: U64Vec2, zw: U64Vec2) : this(xy.x, xy.y, zw.x, zw.y)

    operator fun get(i: Int): ULong = when (i) { 0 -> x; 1 -> y; 2 -> z; 3 -> w; else -> throw IndexOutOfBoundsException(i) }
    /** The same with component i replaced: `v.with(1, value)`. */
    fun with(i: Int, value: ULong) = when (i) { 0 -> copy(x = value); 1 -> copy(y = value); 2 -> copy(z = value); 3 -> copy(w = value); else -> throw IndexOutOfBoundsException(i) }
    fun toArray() = ulongArrayOf(x, y, z, w)
    operator fun plus(o: U64Vec4) = U64Vec4((x + o.x).toULong(), (y + o.y).toULong(), (z + o.z).toULong(), (w + o.w).toULong())
    operator fun plus(s: ULong) = U64Vec4((x + s).toULong(), (y + s).toULong(), (z + s).toULong(), (w + s).toULong())
    operator fun minus(o: U64Vec4) = U64Vec4((x - o.x).toULong(), (y - o.y).toULong(), (z - o.z).toULong(), (w - o.w).toULong())
    operator fun minus(s: ULong) = U64Vec4((x - s).toULong(), (y - s).toULong(), (z - s).toULong(), (w - s).toULong())
    operator fun times(o: U64Vec4) = U64Vec4((x * o.x).toULong(), (y * o.y).toULong(), (z * o.z).toULong(), (w * o.w).toULong())
    operator fun times(s: ULong) = U64Vec4((x * s).toULong(), (y * s).toULong(), (z * s).toULong(), (w * s).toULong())
    operator fun div(o: U64Vec4) = U64Vec4((x / o.x).toULong(), (y / o.y).toULong(), (z / o.z).toULong(), (w / o.w).toULong())
    operator fun div(s: ULong) = U64Vec4((x / s).toULong(), (y / s).toULong(), (z / s).toULong(), (w / s).toULong())
    operator fun rem(o: U64Vec4) = U64Vec4((x % o.x).toULong(), (y % o.y).toULong(), (z % o.z).toULong(), (w % o.w).toULong())
    operator fun rem(s: ULong) = U64Vec4((x % s).toULong(), (y % s).toULong(), (z % s).toULong(), (w % s).toULong())
    operator fun unaryPlus() = this
    infix fun and(o: U64Vec4) = U64Vec4((x and o.x).toULong(), (y and o.y).toULong(), (z and o.z).toULong(), (w and o.w).toULong())
    infix fun and(s: ULong) = U64Vec4((x and s).toULong(), (y and s).toULong(), (z and s).toULong(), (w and s).toULong())
    infix fun or(o: U64Vec4) = U64Vec4((x or o.x).toULong(), (y or o.y).toULong(), (z or o.z).toULong(), (w or o.w).toULong())
    infix fun or(s: ULong) = U64Vec4((x or s).toULong(), (y or s).toULong(), (z or s).toULong(), (w or s).toULong())
    infix fun xor(o: U64Vec4) = U64Vec4((x xor o.x).toULong(), (y xor o.y).toULong(), (z xor o.z).toULong(), (w xor o.w).toULong())
    infix fun xor(s: ULong) = U64Vec4((x xor s).toULong(), (y xor s).toULong(), (z xor s).toULong(), (w xor s).toULong())
    infix fun shl(s: Int) = U64Vec4((x shl s).toULong(), (y shl s).toULong(), (z shl s).toULong(), (w shl s).toULong())
    infix fun shr(s: Int) = U64Vec4((x shr s).toULong(), (y shr s).toULong(), (z shr s).toULong(), (w shr s).toULong())
    fun inv() = U64Vec4(x.inv().toULong(), y.inv().toULong(), z.inv().toULong(), w.inv().toULong())
    fun toVec4() = Vec4(x.toFloat(), y.toFloat(), z.toFloat(), w.toFloat())
    fun toDVec4() = DVec4(x.toDouble(), y.toDouble(), z.toDouble(), w.toDouble())
    fun toIVec4() = IVec4(x.toInt(), y.toInt(), z.toInt(), w.toInt())
    fun toUVec4() = UVec4(x.toUInt(), y.toUInt(), z.toUInt(), w.toUInt())
    fun toI8Vec4() = I8Vec4(x.toByte(), y.toByte(), z.toByte(), w.toByte())
    fun toU8Vec4() = U8Vec4(x.toUByte(), y.toUByte(), z.toUByte(), w.toUByte())
    fun toI16Vec4() = I16Vec4(x.toShort(), y.toShort(), z.toShort(), w.toShort())
    fun toU16Vec4() = U16Vec4(x.toUShort(), y.toUShort(), z.toUShort(), w.toUShort())
    fun toI64Vec4() = I64Vec4(x.toLong(), y.toLong(), z.toLong(), w.toLong())
    override fun toString() = "($x, $y, $z, $w)"

    companion object {
        val Zero get() = U64Vec4(0.toULong())
        val One get() = U64Vec4(1.toULong())
        val UnitX get() = U64Vec4(1.toULong(), 0.toULong(), 0.toULong(), 0.toULong())
        val UnitY get() = U64Vec4(0.toULong(), 1.toULong(), 0.toULong(), 0.toULong())
        val UnitZ get() = U64Vec4(0.toULong(), 0.toULong(), 1.toULong(), 0.toULong())
        val UnitW get() = U64Vec4(0.toULong(), 0.toULong(), 0.toULong(), 1.toULong())
    }
}
/** A U64Vec4 from Longs, as their bits. */
fun U64Vec4(x: Long, y: Long, z: Long, w: Long) = U64Vec4(x.toULong(), y.toULong(), z.toULong(), w.toULong())
fun U64Vec4(s: Long) = U64Vec4(s.toULong())
fun IVec4.toU64Vec4() = U64Vec4(x.toULong(), y.toULong(), z.toULong(), w.toULong())
fun UVec4.toU64Vec4() = U64Vec4(x.toULong(), y.toULong(), z.toULong(), w.toULong())

